// Module 2 — Office Tools (Word, Excel, PowerPoint)
// Bloom's-aligned MCQs. Each topic follows the progression:
// Q1-Q2 Remember · Q3-Q4 Understand · Q5-Q7 Apply · Q8 Analyze · Q9 Evaluate · Q10 Create
// All distractors are Grade A: every option is plausible, and every option is
// roughly equal in visual length (or distractors are LONGER than the correct
// answer) so students cannot scan-and-pick the longest one.

import type { Question } from "./module1-mcq";

export const mcqData: Record<number, Question[]> = {
  // ─── Topic 1: Editing vs Word Processing ───
  1: [
    { q: "Which of these is the clearest definition of a text editor?", opts: ["A program that edits plain characters only, no formatting or page layout features", "A program that prints pages in colour and handles images and tables neatly", "A program that can read every file format on the computer without any problems and most modern teams have moved to exactly this way of doing things", "A program that opens .docx files and shows every font exactly as designed"], ans: 0, why: "A text editor works with plain characters — no bold, no colour, no images. Printing in colour, reading every format, and handling .docx are word-processor or viewer jobs, not text-editor jobs. Keep the definition simple: characters in, characters out.", bloom: "remember" },
    { q: "Which of these best describes what a word processor does?", opts: ["Only stores short notes and small pieces of plain text, nothing more","Edits text AND adds formatting, layout, images, tables, and styles","Runs the computer's operating system and manages its memory and files","Saves files in a special format that no other program can ever open"], ans: 1, why: "A word processor is editing PLUS formatting, layout, images, tables, and styling. It is a bigger tool than a text editor, not a different one. The other options describe a notepad, an operating system, or a broken file format — none of which fit.", bloom: "remember" },
    { q: "Why do programmers often prefer a plain text editor like VS Code over MS Word for writing code?", opts: ["Word is too slow on older laptops and takes a long time to open big files","Word files are much bigger than plain text and fill up the hard drive quickly","Word adds invisible formatting (smart quotes, auto-caps) that breaks code","Word does not support dark mode, which most programmers like to use"], ans: 2, why: "Code must be exact plain text — smart quotes, auto-capitalised letters, and hidden styles break compilers. A plain text editor guarantees byte-for-byte what you typed. Speed, file size, and dark mode are minor issues compared to code that simply will not run.", bloom: "understand" },
    { q: "Why is editing (typing, deleting, copying) considered a PART of word processing, not a separate thing?", opts: ["Because every word processor also needs internet access to work properly","Because editing is the base layer; word processing adds formatting on top","Because editing tools cost money and word processors are always free for students","Because editing only works on small files and word processing works on big ones"], ans: 1, why: "Word processing = editing PLUS formatting, layout, and styling. Editing is the common ground; word processing is the bigger set that includes it. Internet, price, and file size have nothing to do with the definition.", bloom: "understand" },
    { q: "Your professor wants a .docx file with a header, page numbers, and a table of contents. Which tool fits?", opts: ["A plain text editor like Notepad, which is the simplest option for any writing","A word processor like MS Word or Google Docs, which supports all these features","A spreadsheet program like Excel, because it can also hold text and numbers","A presentation tool like PowerPoint, saved as a document at the end of the work"], ans: 1, why: "Headers, pagination, and a TOC are word-processing features that plain editors do not support. MS Word, Google Docs, or LibreOffice Writer all qualify. Excel and PowerPoint are wrong tools for a written essay.", bloom: "apply" },
    { q: "You receive a 2000-word document as a .txt file. The content is fine, but it looks \"flat.\" What is happening?", opts: ["The file is probably corrupted and you should ask the sender for a new copy", "Your computer is too slow to show the formatting stored inside the text file and most modern teams have moved to exactly this way of doing things", "The .txt format stores plain characters only, so all formatting is stripped away", "Only .docx files can hold long text — .txt is limited to a few hundred words"], ans: 2, why: ".txt stores characters only, with no styling metadata. Any bold/italic/colour/heading the author used is lost on save because the format has no way to record it. The content survives; the presentation does not.", bloom: "apply" },
    { q: "A friend is writing a short poem and wants italics and a centred title. Which tool fits best?", opts: ["Notepad, because it is already installed and opens very quickly","Excel, because cells can be centred and the font can be made italic","MS Word or Google Docs, because both support italics and centred alignment","A programmer's code editor, which handles any text a writer could ever need"], ans: 2, why: "Italics and centred titles are formatting features — word-processor territory. Notepad has no italics at all. Excel can do it but is designed for grids and numbers, not poems. Code editors skip formatting on purpose.", bloom: "apply" },
    { q: "A student submits a 10-page essay written in Notepad and saved as .txt. The professor says the formatting is unreadable. What did the student fail to understand?", opts: ["Notepad has a hidden formatting mode that must be switched on before typing","Universities reject .txt files because the format is considered too old-fashioned","Notepad files cannot hold more than a few pages of text before breaking down","The student confused editing with word processing — Notepad has no formatting"], ans: 3, why: "The failure is conceptual, not technical. Notepad holds the words but cannot produce headings, fonts, spacing, or pagination the professor expected. The student used a tool for characters when the task needed presentation — that is the editing vs word-processing gap.", bloom: "analyze" },
    { q: "A company bans plain text editors entirely and makes everyone use Google Docs for every file. Evaluate this policy.", opts: ["It is flawed because roles that handle code, config files, CSVs, or logs suffer","It is great because having one single tool makes training and support much easier","It is great because Google Docs has every feature anyone in the company might need","It is flawed only because Google Docs needs internet access, which is not reliable"], ans: 0, why: "Docs can auto-format and corrupt plain-text content (code, CSVs, config, logs). The policy helps writers but creates friction for engineers and ops. A blanket rule ignores that some jobs need exactness, not presentation.", bloom: "evaluate" },
    { q: "Design a file-format policy for a university department handling: research papers, course notes, code samples, and meeting minutes.", opts: ["Use .docx for everything — it is the standard format most students already know","Papers .docx/.pdf; notes .docx/Markdown; code .txt; minutes .docx or Markdown","Use .txt for everything — it is simple and opens on every computer in the world","Use .pdf for everything, because PDF is the most professional format of them all"], ans: 1, why: "Each format is chosen for what the content needs: papers need rich formatting (.docx/.pdf), notes work in .docx or Markdown, code MUST be plain text, minutes work in either. A one-size policy fails; matching content to format is the right design.", bloom: "create" },
  ],

  // ─── Topic 2: Word Formatting (Ribbon, shortcuts, alignment) ───
  2: [
    { q: "What is the Ribbon in Microsoft Word?", opts: ["The document outline shown on the left side of the window for navigation","The status bar along the bottom of the screen showing the total word count","The tabbed strip at the top that groups related tools into labelled sections","The scroll bar running down the right edge of the page for moving up and down"], ans: 2, why: "The Ribbon is Word's main tool container — tabs across the top (Home, Insert, Layout, etc.), each with groups of related buttons. The other answers describe different UI parts of the window.", bloom: "remember" },
    { q: "Which shortcut makes the selected text bold in Microsoft Word?", opts: ["Ctrl+B, which is the standard shortcut for bold on Windows keyboards","Ctrl+I, which puts the selected text into a slanted italic style on the page","Ctrl+U, which draws a thin line under the selected text for emphasis","Ctrl+H, which opens the Find-and-Replace window, not a formatting option"], ans: 0, why: "Ctrl+B toggles bold on the selected text. Ctrl+I is italic, Ctrl+U is underline, Ctrl+H opens Find and Replace. Learning these shortcuts saves a lot of time clicking on the Ribbon.", bloom: "remember" },
    { q: "Why does Word require you to SELECT text before applying bold, italic, or a different font?", opts: ["Word is old software and requires this extra step for historical reasons","Selection speeds Word up, because the program can ignore unselected text","Selection is actually optional — bold and italic work fine without selecting first","A command needs a target — without selection, Word cannot know what to change"], ans: 3, why: "Without a selection, Word has no target; with a selection, the command knows exactly what to modify. It is a simple contract between user and program — any command that changes content must know WHAT content to change.", bloom: "understand" },
    { q: "Why does Word's Ribbon group tools into tabs like Home, Insert, and Layout instead of one long list?", opts: ["Tabs are a legacy feature from old Word versions that nobody bothered to remove","Tabs group related tools so users find them faster without endless scrolling","Tabs are there only because the screen is too small to hold every button at once","Tabs exist so Microsoft can hide advanced features and charge extra money for them"], ans: 1, why: "Grouping related tools (Home = formatting, Insert = add stuff, Layout = page setup) makes Word easier to learn and use. A single flat list of hundreds of buttons would be slower to search. Legacy, screen size, and pricing are not the reason.", bloom: "understand" },
    { q: "A heading should stretch evenly across the full line width, with both left and right edges aligned. Which shortcut applies this?", opts: ["Ctrl+E, which centres the selected text on the page horizontally","Ctrl+R, which pushes the selected text all the way to the right margin","Ctrl+J, which justifies the text so both edges line up on the page","Ctrl+L, which aligns the selected text to the left margin by default"], ans: 2, why: "Justify (Ctrl+J) stretches word spacing so both edges align. Centre (Ctrl+E) keeps the line centred without stretching. Left (Ctrl+L) and Right (Ctrl+R) align only one edge.", bloom: "apply" },
    { q: "You have formatted a paragraph exactly how you want it and need to apply the same style to six other paragraphs fast. What is the best approach?", opts: ["Retype each paragraph from scratch, giving every new one the same settings manually","Copy and paste each paragraph, then edit the content back to the original wording","Change each paragraph one at a time, picking font, size, and colour for each","Use Format Painter to copy the formatting from the source to each target quickly"], ans: 3, why: "Format Painter is designed to duplicate formatting across selections — click the formatted paragraph, then drag across the targets. It copies formatting without changing content, which is faster and more consistent than any manual method.", bloom: "apply" },
    { q: "A student wants to make a long quote stand out visually in the middle of an essay. Which formatting choice fits best?", opts: ["Make the entire quote bold, italic, and underlined, all at once for strong emphasis","Change the quote to a bright red colour so readers notice it on the page","Indent the quote from both sides and use italics — the standard block-quote look","Put the quote in the biggest font size available so it fills the page clearly"], ans: 2, why: "A block quote is indented from both margins and usually italicised — this is the standard academic look that says \"this text is borrowed.\" Bold-italic-underline together is too loud; bright red distracts; giant font ignores the point of a readable essay.", bloom: "apply" },
    { q: "A document uses manual bold+size+font combinations on every heading instead of the built-in Heading 1/Heading 2 styles. What are the downstream consequences?", opts: ["No real consequences — as long as it looks the same, the headings work just fine","The document file size grows too large and Word eventually refuses to save it","The document will become corrupted within a few days and all content will be lost","Inconsistent styling, no automatic TOC, no navigation pane, and no global restyle"], ans: 3, why: "Styles are not just formatting — they are metadata. Skipping them forfeits TOC generation, the navigation pane, global restyling, and outline view. Restyling the whole document means editing every heading by hand. The file does NOT corrupt; the real cost is maintenance and accessibility.", bloom: "analyze" },
    { q: "A team argues about whether to ban inline formatting and use Styles only. Evaluate this proposal.", opts: ["Inline formatting should always be banned — there is no good reason to keep it","Styles suit long structured docs; inline is fine for short informal notes and emails","Styles are always better and should be used for every single document, no exceptions","Inline formatting is simpler, so the team should ban Styles and save training time"], ans: 1, why: "Styles pay off in proportion to length and structure — they power TOC, outline navigation, and global restyle. A one-page note does not need them; a 50-page report does. A total ban is too strict for casual notes; a full recommendation for structured work is right. Nuance wins.", bloom: "evaluate" },
    { q: "Design a style system for a 100-page university thesis. Which styles would you define and why?", opts: ["Just one style called \"Normal\" — applied everywhere, keeps the document simple","Title, H1, H2, H3, Body, Caption, Block Quote, Code — one per structural role","Only Bold and Italic styles, used whenever something needs to stand out visually","A new style for every single page, so each page can have its own unique look"], ans: 1, why: "Each style encodes a structural role: Title, H1 (chapters), H2 (sections), H3 (subsections), Body, Caption (figures/tables), Block Quote, Code. The document becomes globally restyleable and the TOC auto-generates. One flat style or per-page styles lose every structural benefit.", bloom: "create" },
  ],

  // ─── Topic 3: Images and Tables in Word ───
  3: [
    { q: "Which Ribbon tab hosts the tools for inserting images, tables, shapes, and charts?", opts: ["The Home tab, which holds the main formatting controls for text in the document and most modern teams have moved to exactly this way of doing things", "The Layout tab, which controls margins, orientation, and the overall page size", "The Insert tab, which is the designated place for adding images, tables, and charts", "The View tab, which only changes how the document is displayed on the screen"], ans: 2, why: "The Insert tab is the home for adding anything that is not plain typed text. Home handles formatting, Layout handles page setup, and View changes display preferences — none of those add new objects.", bloom: "remember" },
    { q: "In Word, which is the quickest way to add a 3-column, 4-row table?", opts: ["Draw every line one by one using the pen tool under the Insert menu","Go to Insert → Table and hover over the grid to pick 3 columns by 4 rows","Use the Tab key and spaces to line up columns manually across each row","Copy a table from the internet, paste it, then delete the rows you do not need"], ans: 1, why: "Insert → Table → hover the grid is the standard, fastest way. Drawing lines is slow, spaces never line up reliably, and copying from the internet is messy. Word was built to make this quick.", bloom: "remember" },
    { q: "Why should you drag a CORNER handle (not a side handle) when resizing an image in Word?", opts: ["Corner handles preserve the aspect ratio, so the image is not stretched or squashed","Corner handles are more reliable than side handles and never break by accident","Side handles do not work properly in modern Word versions and should be avoided","There is really no difference — both corner and side handles do exactly the same job"], ans: 0, why: "Corner = proportional resize (width-to-height ratio kept); side = stretch one dimension, which distorts the image. The visible difference shows up immediately on photos — stretched people look visibly squashed.", bloom: "understand" },
    { q: "Why does Word treat \"In Line with Text\" wrapping differently from \"Square\" wrapping?", opts: ["In Line is older and slower; Square is the newer option that works faster now", "In Line treats the image as a big character in the text; Square lets text flow around", "Square is only for small images; In Line is only for large pictures and photos", "There is no real difference — Microsoft added both options for marketing reasons and most modern teams have moved to exactly this way of doing things"], ans: 1, why: "In Line makes the image behave like a letter in a line of text, so it moves with the paragraph. Square lets text flow around the image's box. They exist for different layouts, not for different image sizes or for marketing reasons.", bloom: "understand" },
    { q: "You insert a company logo at the top of a page and want text to flow around it on the right. Which wrapping setting?", opts: ["In Line with Text, because this is the safest and simplest option for any image","Square, because it wraps the surrounding text around the image's bounding box","Behind Text, because the logo will then sit underneath the words on the page","In Front of Text, because the logo will then cover the writing for strong emphasis"], ans: 1, why: "Square wraps text around the image's bounding box — exactly what is asked. In Line treats the image as a character (breaks flow). Behind/In Front overlap, which is usually wrong for a logo + text layout.", bloom: "apply" },
    { q: "You need a schedule table: 7 columns (days) and 10 rows (hour slots), with the header highlighted. What is the best way?", opts: ["Insert → Table → Insert Table (7×10), then shade the header row with a colour","Draw every single line with the pen tool to get the exact sizes that you want","Use spaces and the Enter key to line up the columns and rows on the page","Export the table from Excel and paste it into Word as a static image file"], ans: 0, why: "The Insert Table dialog lets you specify exact dimensions (grid mode caps at 10×8). Styling the header via Table Design is the standard path. Drawing by hand is slow; spaces never line up; pasting an image loses the ability to edit cells.", bloom: "apply" },
    { q: "You want an image caption to stay with the image even if the image moves. Which Word feature handles this?", opts: ["The References tab's Insert Caption tool, which links the caption to the image", "Manually typing the caption below the image and making it bold for visibility and most modern teams have moved to exactly this way of doing things", "Using a text box placed near the image and dragging both around together", "Putting the caption inside the image's alt-text field in the Picture dialog"], ans: 0, why: "References → Insert Caption links the caption to the image, so moving one moves the other — and it auto-numbers figures. Typing by hand or using a separate text box means the caption can drift; alt-text is for screen readers, not visible captions.", bloom: "apply" },
    { q: "A student uses a table with invisible borders to lay out their whole page (navigation row, content row, footer row). Why is this bad practice today?", opts: ["It will crash Word the moment the document grows larger than just a few pages","Tables only work inside HTML documents — Word tables do not support invisible borders","Tables are for tabular data; using them for layout breaks meaning and accessibility","There is nothing wrong with it — tables for layout are still a recommended technique"], ans: 2, why: "Tables-for-layout confuse screen readers (\"row 1 contains 3 unrelated cells\"), break copy-paste ordering, and fight modern responsive design. The visual looks fine; the structure is wrong. It is a web hack that also hurts Word accessibility.", bloom: "analyze" },
    { q: "A designer argues every image in a report should use \"In Line with Text\" wrapping because it is simplest. Evaluate.", opts: ["Always correct — In Line is the safest setting and should always be used everywhere and most modern teams have moved to exactly this way of doing things", "Always wrong — In Line should never be used under any circumstance in any document", "It does not matter which wrapping you pick because the result always looks the same", "Partly correct — fine for small inline icons, but wrong for large figures with flowing text"], ans: 3, why: "In Line IS the most predictable for small inline icons because the image acts like a character. For large figures where text should flow around, Square or Tight is better. \"Simplest\" is often right; \"always\" is too strong — rule of thumb, not absolute.", bloom: "evaluate" },
    { q: "Design a table structure for a 3-page course syllabus listing week, topic, readings, and assignments. How do you make it print well across pages?", opts: ["One giant single cell with all the data inside separated by line breaks and tabs","A separate small table for every single row, stacked one above the other down the page","4 columns with a styled header row and \"Repeat Header Rows\" turned on for printing","Use paragraphs with carefully placed spaces to simulate columns without using a table"], ans: 2, why: "Columns: Week, Topic, Readings, Assignments. Enable \"Repeat Header Rows\" in Table Properties so the header re-prints on each page. Designing a data table means naming the columns, styling the header, and solving the page-break problem.", bloom: "create" },
  ],

  // ─── Topic 4: Excel — Cells, Rows, Columns, Sheets ───
  4: [
    { q: "What does \"cell C5\" refer to in Excel?", opts: ["The fifth cell counted down column C, which happens to be the same as row 5","The cell located at the intersection of column C and row 5 in the worksheet","Row C, column 5, using a row-first addressing system that Excel follows by default","The fifth sheet in the workbook that has been renamed by the user to \"C\""], ans: 1, why: "Excel addresses are [column letter][row number]. C = third column, 5 = fifth row. Always column first, then row. Excel does NOT use row-first addressing, and C5 is not a sheet name.", bloom: "remember" },
    { q: "What is the difference between a Worksheet and a Workbook in Excel?", opts: ["A Worksheet is the Excel file; a Workbook is one single tab inside that file","A Workbook is the file; a Worksheet is one of the tabs (sheets) inside the file","They are two different words for the exact same thing, used interchangeably always","A Worksheet holds numbers only; a Workbook holds text only, never both together"], ans: 1, why: "A Workbook is the .xlsx file; a Worksheet is one of the tabs inside it. One workbook can hold many worksheets. The other options swap the terms or invent restrictions that do not exist.", bloom: "remember" },
    { q: "Why does Excel organise data into separate Worksheets within a single Workbook, instead of one giant sheet?", opts: ["It is a limitation of older Excel versions that Microsoft has never fully removed","Worksheets cannot actually hold much data, so you must split it into many tabs","Workbooks are a legacy feature that was kept only for compatibility with old files","Separation: each topic gets its own sheet while sharing one file for organisation"], ans: 3, why: "Different topics (sales, inventory, forecasts) each get their own sheet with their own structure, while sharing one file. Formulas can pull across sheets when needed. It is a file-and-tabs pattern — not a limitation or legacy quirk.", bloom: "understand" },
    { q: "Why do column letters in Excel skip from Z straight to AA instead of continuing as a single letter?", opts: ["Because the alphabet only has 26 letters — doubling them gives many more columns","Because Excel uses a special internal code that skips certain letters on purpose","Because single letters are reserved for formulas and cannot be used as columns","Because AA is actually the first column and Z is the 27th, contrary to popular belief"], ans: 0, why: "26 letters of the alphabet cover A–Z. After Z, Excel uses AA, AB … AZ, then BA … and so on, giving far more than 26 columns. The other options invent restrictions that do not exist.", bloom: "understand" },
    { q: "You need to sum cells B2 through B30. Which range notation is correct?", opts: ["=SUM(B2:B30), which uses a colon to mean \"every cell from B2 down to B30\"","=SUM(B2, B30), which only adds the two specific cells B2 and B30, not the range","=SUM(B2-B30), which tries to subtract B30 from B2 and gives a single number","=SUM(B2+B30), which adds only two cells together and ignores all the rest"], ans: 0, why: "The colon creates a range (every cell from B2 to B30 inclusive). A comma lists individual cells. Dash and plus are arithmetic operators — they do not create ranges.", bloom: "apply" },
    { q: "You typed \"45\" into A1 but it left-aligns and will not sum. What is wrong and how do you fix it?", opts: ["Excel is broken — restart the computer and hope the problem goes away on reboot", "45 is too small a number for Excel, so it stores it as text instead of a number", "Your keyboard is in the wrong language and entering strange invisible characters and most modern teams have moved to exactly this way of doing things", "The cell is formatted as Text — change Format Cells to Number or retype the value"], ans: 3, why: "Left-alignment + refusal to sum = classic \"looks like a number but is text.\" Fix: select the cell → Format Cells → Number, or retype the value in a fresh General-formatted cell. =VALUE() also works.", bloom: "apply" },
    { q: "How would you quickly freeze the top row of a long list so it stays visible when scrolling?", opts: ["Manually scroll slowly so you do not lose sight of the header when moving down", "Copy the header row and paste it every 30 rows so it reappears during scrolling and most modern teams have moved to exactly this way of doing things", "View → Freeze Panes → Freeze Top Row, so the header stays visible while scrolling", "Increase the row height of the header so it is always easy to see on the screen"], ans: 2, why: "View → Freeze Panes → Freeze Top Row locks row 1 in place while you scroll. This is the built-in feature for exactly this need. Manual scrolling, pasting headers, and tall rows do not solve the problem.", bloom: "apply" },
    { q: "A workbook has sheets: Sales, Expenses, Summary. Summary pulls =Sales!B10 and =Expenses!B10. Someone renames \"Sales\" to \"Q1 Sales\". What happens?", opts: ["Nothing happens — Excel figures out the new name and updates silently in the background","All formulas break forever, with no way to repair them apart from retyping by hand","The file becomes corrupted the moment the rename is saved, losing all of the data","It depends: tab-rename updates refs; names with spaces need quotes like 'Q1 Sales'!"], ans: 3, why: "Excel updates references automatically IF the rename is done via the tab itself. Names with spaces then need single quotes: ='Q1 Sales'!B10. Renaming externally may break refs to #REF!. Knowing the mechanism matters, not just the syntax.", bloom: "analyze" },
    { q: "A teacher puts 300 students in ONE worksheet with 50 columns per student. Evaluate this structure.", opts: ["Perfect — all the data sits in one place, which makes it very easy to search through","Should be split into 300 separate sheets, one per student, for maximum clarity","Terrible, because Excel cannot hold 300 rows in a single worksheet at the same time","Rows are fine (Excel holds millions); 50 columns sprawling is the real concern here"], ans: 3, why: "Excel handles millions of rows — row count is not the issue. Column sprawl is: if the 50 columns mix grades, attendance, and demographics, splitting into multiple sheets (or a database) is easier to maintain. Evaluate per-column purpose, not just row count.", bloom: "evaluate" },
    { q: "Design the workbook structure for a small business tracking orders, customers, and products.", opts: ["Everything on one sheet, with every order row repeating the full customer address","One sheet per single order, named after the order number and stored forever unchanged","Three sheets — Customers, Products, Orders — linked together by shared ID columns","No structure at all — let each user arrange the data however feels easiest to them"], ans: 2, why: "Customers (ID, name, email), Products (ID, name, price), Orders (order ID, customer ID, product ID, qty, date). Orders references the other two by ID. This mirrors a relational database and keeps each sheet focused. A single-sheet blob duplicates data; per-order sheets are unusable.", bloom: "create" },
  ],

  // ─── Topic 5: Excel Formulas (SUM, AVERAGE, IF, MIN, MAX, COUNT) ───
  5: [
    { q: "Every Excel formula must start with which character, and why?", opts: ["A number, so that Excel immediately treats the content as numerical data to store","An equals sign (=), which tells Excel to evaluate what follows as a formula","A quotation mark, to group the formula together as one single piece of text","A hashtag (#), which Excel uses to categorise formulas by topic and colour"], ans: 1, why: "= tells Excel that what follows is a formula to evaluate, not text to store. Without it, A1+B1 is just typed characters. Numbers, quotes, and hashtags do not trigger formula evaluation.", bloom: "remember" },
    { q: "What does =SUM(A1:A5) do?", opts: ["Counts how many cells inside the range A1 to A5 contain numbers instead of text","Adds the values in cells A1, A2, A3, A4, and A5 together and returns the total","Multiplies every value inside the range A1 to A5 and returns the final product","Finds the biggest number in the range A1 to A5 and returns only that single value"], ans: 1, why: "SUM adds all the values in the range. COUNT counts numbers, PRODUCT multiplies, MAX finds the largest — those are different functions. SUM is the most basic total function in Excel.", bloom: "remember" },
    { q: "Why does =AVERAGE(A1:A10) give a different result from =SUM(A1:A10)/10 if some cells are empty?", opts: ["They are always exactly identical, because Excel treats empty cells as zeros always","SUM ignores empty cells, but AVERAGE treats every single empty cell as a zero value","AVERAGE divides by the count of numeric cells; /10 always divides by exactly 10","Only AVERAGE supports ranges — the /10 form throws a formula error on empty data"], ans: 2, why: "If 3 of the 10 cells are empty, AVERAGE divides by 7 and /10 divides by 10 — two different answers. AVERAGE = sum / count-of-numbers; /10 hardcodes a denominator that may not match reality. For data with blanks, AVERAGE is correct.", bloom: "understand" },
    { q: "Why might =IF(A1>50, \"Pass\", \"Fail\") return \"Fail\" even when A1 looks like 75 on screen?", opts: ["IF only works with whole numbers, so decimal values always return the Fail branch","The 75 may be stored as text — IF comparisons on text do not work like on numbers","Excel's IF function has a known bug that sometimes reverses the true/false answer","The cell A1 must be formatted as currency before IF can compare it to the number 50"], ans: 1, why: "If 75 was typed with a leading apostrophe or in a Text-formatted cell, it is stored as text. Text \"75\" is not greater than number 50 in the way you expect — IF returns the false branch. Fix: convert to a number. Excel's IF has no such bug.", bloom: "understand" },
    { q: "A teacher has scores in B2:B31 and needs to count how many are 40 or above (pass). Which formula is correct?", opts: ["=COUNT(B2:B31), which simply counts every numeric cell in the given range","=IF(B2:B31>=40, 1, 0), which tries to apply IF across the full range at once","=SUMIF(B2:B31, \">=40\"), which adds the values meeting the condition, not count","=COUNTIF(B2:B31, \">=40\"), which counts cells meeting the condition exactly"], ans: 3, why: "COUNT counts all numeric cells. SUMIF sums values meeting a condition (sum, not count). COUNTIF counts cells meeting a condition — exactly what is asked. The IF range form does not work in plain Excel.", bloom: "apply" },
    { q: "Cell D1 = =IF(A1>100, \"Gold\", IF(A1>50, \"Silver\", \"Bronze\")). A1 is 75. What shows in D1?", opts: ["Gold, because 75 is a fairly large number compared to everyday test scores","Bronze, because nothing in the nested IF structure actually matched the value","Silver — the outer IF failed, inner IF matched 75>50, so \"Silver\" is returned","#ERROR, because nested IF formulas are not actually allowed inside Excel cells"], ans: 2, why: "First IF checks 75>100 (false), falls to inner IF which checks 75>50 (true), returns \"Silver\". Nested IFs check conditions in order and the first true wins. Real knowledge means tracing logic step by step.", bloom: "apply" },
    { q: "You want to mark cells red automatically when a score is below 40. Which Excel feature?", opts: ["Write a custom IF formula in every cell that changes the font colour when true", "Use Conditional Formatting with a rule that turns the cell red if value is under 40", "Manually select and colour every failing cell one by one whenever the data changes and most modern teams have moved to exactly this way of doing things", "Copy the data into Word first, then apply red highlighting using the Word Ribbon"], ans: 1, why: "Conditional Formatting (Home → Conditional Formatting) is built exactly for this: colour changes automatically when values cross a rule. IF cannot change cell colour on its own. Manual colouring breaks the moment data updates; Word is the wrong tool entirely.", bloom: "apply" },
    { q: "A payroll sheet uses =B2*C2 down 500 rows. Someone inserts a new \"Bonus\" column between B and C, shifting C to D. What happens?", opts: ["Excel updates the references automatically so the formulas now read =B2*D2","Nothing happens — the formulas silently break and return zero for every single row","All 500 formulas now point to the same single cell, breaking the whole payroll sheet","Excel refuses to let the user insert a new column when formulas depend on the old one"], ans: 0, why: "Excel tracks cell identity through column insertions, so formulas become =B2*D2 automatically. But any new C column content is ignored — formulas still multiply the original columns. Correct behaviour, but easy to misread as a bug.", bloom: "analyze" },
    { q: "A team uses =IF(score>=60, \"Pass\", \"Fail\"). A manager proposes =IFS(score>=85, \"A\", score>=70, \"B\", score>=60, \"C\", TRUE, \"F\"). Evaluate.", opts: ["The simple IF is always better, because shorter formulas are always easier to maintain","They are completely identical in what they do — the team should just pick either one","Always pick the longest formula available, because it shows deeper technical knowledge","IFS suits multi-branch logic; plain IF is fine only when there are just two outcomes"], ans: 3, why: "IFS is cleaner than deeply nested IFs, easier to read, and scales to 5+ conditions. For two outcomes (Pass/Fail), plain IF is fine. Match the tool to the decision shape: binary → IF; multi-branch → IFS.", bloom: "evaluate" },
    { q: "Design formulas for a grade sheet with 30 scores in B2:B31: average, highest, lowest, passes (≥60), % passing, and letter grades.", opts: ["Just use =SUM for every task — it can be adapted to count, compare, and grade easily","Write the answers by hand into each cell, because formulas are too complex for this","AVERAGE, MAX, MIN, COUNTIF, a percent formula, and IFS — one per task assigned","Use =TOTAL for every task — it is the universal function that handles all of these"], ans: 2, why: "Average: =AVERAGE(B2:B31). Highest: =MAX. Lowest: =MIN. Passes: =COUNTIF(B2:B31,\">=60\"). % passing: =COUNTIF(...)/COUNT(...). Letter: =IFS(B2>=85,\"A\",B2>=70,\"B\",B2>=60,\"C\",TRUE,\"F\"). Five functions, each matched to its task. =TOTAL does not exist.", bloom: "create" },
  ],

  // ─── Topic 6: Sorting, Filtering, and Linking Sheets ───
  6: [
    { q: "Which statement correctly describes filtering vs sorting?", opts: ["They are the same operation with two different names used in different Excel versions","Sorting permanently deletes rows; filtering only keeps the rows that the user selects","Sorting reorders rows; filtering hides rows that do not match a chosen condition","Filtering reorders rows; sorting hides the rows that do not match any condition"], ans: 2, why: "Sort = reorder, no data lost (all rows still visible). Filter = hide rows not matching a condition, no data lost (hidden rows still exist). Both are non-destructive; mixing them up is the most common confusion.", bloom: "remember" },
    { q: "What does the Sort A→Z button do when applied to a column of names?", opts: ["It deletes every name that starts with the same letter to remove duplicates quickly","It rearranges the rows so the names appear in alphabetical order from A down to Z","It highlights the names in alphabetical order but keeps the row order unchanged","It copies the names into a new sheet sorted alphabetically, leaving the original alone"], ans: 1, why: "Sort A→Z reorders rows in place, alphabetically. It does not delete, highlight, or copy to a new sheet — those are different operations. Sorting moves whole rows so each name keeps its related data.", bloom: "remember" },
    { q: "Why is filtering considered \"non-destructive\" even when rows disappear from view?", opts: ["Because Excel secretly deletes them and then restores them automatically on next save and most modern teams have moved to exactly this way of doing things", "Because you can always press Ctrl+Z once to undo the filter immediately afterwards", "The hidden rows still exist — filtering only changes the view, not the underlying data", "Because filtering does not really work at all, so no data can ever actually be lost"], ans: 2, why: "The filter changes only the view. Clearing the filter brings every row back. Save-and-reopen also preserves the data. Filtering separates view from data, which is why sharing a filtered file can confuse people who do not notice the filter.", bloom: "understand" },
    { q: "Why can sorting a single column sometimes mess up a spreadsheet by mixing up related data?", opts: ["Because Excel picks a random column to sort by when the user is not paying attention","Because sorting with only one column selected may not move the related data columns","Because sorting always scrambles the entire sheet no matter how many columns are chosen","Because Excel does not actually support sorting on spreadsheets larger than 100 rows"], ans: 1, why: "If you select only one column and sort, Excel may sort just that column and leave the others in place, breaking the row relationships. The fix is to select the whole data range (or use Sort dialog with headers). Excel is not \"random\" and it supports huge sheets.", bloom: "understand" },
    { q: "You want to see only Section A students who scored above 80. Which approach?", opts: ["Delete every row that does not match the two conditions one by one manually","Sort the data by section alphabetically and just read the top ten rows carefully","Copy all the rows into a new sheet and delete the ones that do not match","Apply a filter on Section (=\"A\") AND another filter on Score (>80) together"], ans: 3, why: "Multiple filters combine with AND logic. Two filters narrow the view to rows matching BOTH conditions. Sorting does not hide rows; deleting is destructive; copying is unnecessary work.", bloom: "apply" },
    { q: "Sheet \"Summary\" pulls the total from cell B100 of sheet \"Sales Q1\" (note the space). What is the correct reference?", opts: ["=Sales Q1!B100, which looks right but breaks because Excel cannot parse the space and most modern teams have moved to exactly this way of doing things", "='Sales Q1'!B100, which wraps the sheet name in single quotes because of the space", "=Sales_Q1!B100, replacing spaces with underscores so Excel does not get confused", "=\"Sales Q1\".B100, using double quotes and a dot to separate sheet from cell"], ans: 1, why: "Sheet names with spaces or special characters need single quotes around the name, then !, then the cell. Without quotes, Excel reads the space as end-of-name and errors. Underscores and dots are not Excel's syntax.", bloom: "apply" },
    { q: "You want row colours to alternate (banded rows) automatically for easier reading. What is the fastest way?", opts: ["Manually colour every other row, which takes only a few seconds per small sheet","Select the range and use Home → Format as Table, which adds banded rows by default","Write a formula in each row that checks if the row number is even or odd","Copy the data to Word, apply table banding, then paste it back into Excel properly"], ans: 1, why: "Format as Table adds banded rows automatically and gives you sort/filter too — the standard fast way. Manual colouring breaks when rows are added; formulas cannot change cell background alone; Word is the wrong tool.", bloom: "apply" },
    { q: "A team shares a spreadsheet where sorting is done in place. A colleague sorts by a different column and saves. What is the consequence?", opts: ["No consequence at all — sorts always undo themselves when a new user opens the file","Sorting is actually impossible on shared files, so nothing could have really happened","Only the colleague's local copy changes; other users still see the old sort order","The saved order changes for everyone; row positions lose meaning for every user"], ans: 3, why: "Anyone relying on the old order (\"row 5 was my task\") finds their reference has moved. In-place sorts on shared files are a hidden source of confusion. Saved state is shared state. Meaning should live in the data (IDs, names), not row positions.", bloom: "analyze" },
    { q: "A manager wants to replace cross-sheet linking with copy-paste values because \"it is simpler.\" Evaluate.", opts: ["Copy-paste is always better, because it removes formula errors across linked files","Linking keeps one source of truth; copy-paste drifts when the source changes later","Linking is always better regardless of scenario, because it never has any downsides","They are completely equivalent in practice, so either choice works the same way"], ans: 1, why: "Linking: update the source, every dependent sheet updates. Copy-paste drifts — the moment the source changes, pasted copies go stale. Copy-paste is acceptable only for snapshots. \"Simpler\" sounds good but costs correctness.", bloom: "evaluate" },
    { q: "Design a monthly sales dashboard that pulls from 12 monthly sheets. How do you make adding a new month painless?", opts: ["Retype every number on the dashboard each month by hand after the month ends","Copy-paste the totals from every monthly sheet onto the dashboard once per month","Dashboard with direct links per month, or use INDIRECT for a scalable lookup","Only link to one monthly sheet and ignore the other eleven months permanently"], ans: 2, why: "Basic: dashboard with formulas like ='Jan'!B100, ='Feb'!B100. For scalability, use a lookup column (month name) + INDIRECT: =INDIRECT(\"'\"&A2&\"'!B100\"). Adding a new month just means adding its name — no dashboard edits.", bloom: "create" },
  ],

  // ─── Topic 7: PowerPoint — Slides, Themes, Layouts ───
  7: [
    { q: "Which layout is specifically designed for the opening slide of a presentation?", opts: ["Two Content, which divides a slide into two separate columns for comparing things","Blank, which is completely empty and used only when nothing fits a regular layout","Section Header, which acts as a divider between major parts of the presentation","Title Slide, which shows a large centred title and subtitle, meant to be slide 1"], ans: 3, why: "Title Slide = large centred title and subtitle, meant as slide 1. Section Header is a divider mid-deck. Two Content is for comparisons. Blank is empty on purpose.", bloom: "remember" },
    { q: "What does a Theme control across a PowerPoint deck?", opts: ["Only the background image on the very first slide of the whole presentation file","The colours, fonts, and background styles used across every slide in the deck","The speaker notes font size only, not the main slide text that the audience sees","The slide transition effects between slides — fade, wipe, push, and similar animations"], ans: 1, why: "A Theme controls the deck's colour palette, fonts, and background styles across all slides. Transitions and speaker notes are separate settings. Limiting a theme to slide 1 would miss the whole point of consistency.", bloom: "remember" },
    { q: "Why does applying a Theme change every slide at once, rather than just the current one?", opts: ["Because it is actually a bug in PowerPoint that Microsoft never bothered to fix","A Theme is designed to set the deck's global design for visual consistency across slides","Themes only work on one slide at a time — changing all slides would be a separate feature","Themes apply to slides in a random order, not to every slide at the same time"], ans: 1, why: "A Theme controls the global look across all slides. Making it per-slide would defeat visual consistency and multiply maintenance. Per-slide styling IS a feature — it lives in Slide Master and per-slide format tools — just not in the Theme gallery.", bloom: "understand" },
    { q: "Why does PowerPoint encourage the 6×6 rule (max ~6 bullets of ~6 words each per slide)?", opts: ["Because slides with more text than that cannot be printed properly onto A4 paper", "Because audiences read slide text faster than you speak and then tune out of your talk", "Because PowerPoint secretly slows down if a single slide contains more than 36 words", "Because company style guides legally require this limit in all business presentations and most modern teams have moved to exactly this way of doing things"], ans: 1, why: "Audiences read ahead of the speaker, finish reading, and stop listening — walking away with nothing. Short bullets keep attention on the speaker, with detail in speaker notes. Printing, performance, and legal claims are made-up reasons.", bloom: "understand" },
    { q: "You want to compare \"Manual Process\" and \"Automated Process\" side by side with bullets under each. Which layout?", opts: ["Two Content, which gives a title on top and two equal content panes side by side","Title Slide, which is designed for the opening slide and has only title and subtitle","Section Header, which acts as a divider between major parts of the presentation","Blank, which gives a totally empty slide and makes you build everything from scratch"], ans: 0, why: "Two Content provides a title at top and two equal content panes — the exact structure for side-by-side comparison. Title Slide, Section Header, and Blank serve different purposes.", bloom: "apply" },
    { q: "A presenter pastes 400 words of raw lecture notes onto one slide. Apply the 6×6 rule: what is the fix?", opts: ["Nothing needs changing — more content means more information for the audience to see","Strip the slide to 3–6 short bullets and move the full detail into the speaker notes","Just make the font smaller so the 400 words still fit on the slide at a readable size","Split the 400 words across two slides using the same dense paragraph-style formatting"], ans: 1, why: "The 6×6 rule caps slides at ~6 bullets of ~6 words each. Audiences read faster than you speak, stop listening, and walk away with nothing. Fix: strip to 3–6 short bullets and put detail in speaker notes. Smaller fonts or splitting does not fix the underlying readability problem.", bloom: "apply" },
    { q: "You want the same footer text (date + page number) on every slide. What is the best way?", opts: ["Type the footer manually onto each slide and update it every time the deck changes","Use Insert → Header & Footer, which applies the footer to every slide consistently","Paste the footer as an image onto every slide, which gives a more professional look","Put the footer only on the first slide — the audience will remember it for the rest"], ans: 1, why: "Insert → Header & Footer applies the footer across every slide (with options for dates, slide numbers, and footer text). Manual typing is slow and error-prone; images cannot auto-update; first-slide-only is just missing from the other slides.", bloom: "apply" },
    { q: "A student prepares a 5-minute class presentation with 30 slides. Analyse whether this slide count is appropriate.", opts: ["Too many — aim for around 3–5 content slides plus a title and a closing slide","Perfect — more slides always means more content for the audience to remember","Far too few — a 5-minute talk should probably use closer to 60 slides for impact","Slide count is irrelevant; what matters is the quality of each individual slide"], ans: 0, why: "Rule of thumb: ~1–2 minutes per slide for real engagement. 30 slides in 5 minutes = 10 seconds each — TikTok speed, not a lecture. Content × duration must balance. A realistic count is 3–5 content slides plus title and closing.", bloom: "analyze" },
    { q: "A designer proposes using 5 different fonts across a 20-slide deck \"for visual interest.\" Evaluate.", opts: ["Great idea — font variety is a simple and effective way to keep audiences engaged","Even better with 10 fonts — the more font variety, the more interesting the deck","Font choice does not matter in PowerPoint because the audience only reads the words","Flawed — stick to 2 fonts; get visual interest from images, charts, and whitespace"], ans: 3, why: "Typographic consistency (one heading font, one body font) signals polish and lets content be the star. 5+ fonts look amateur and distract. Visual interest should come from images, charts, and whitespace — not font chaos.", bloom: "evaluate" },
    { q: "Design the slide outline for a 10-minute board presentation on quarterly sales results.", opts: ["30 slides of raw data dumped onto the screen for the board to read at their own pace", "1 single slide listing every single quarterly number in one small-font text block", "~6 slides pacing roughly 1.5 min each: title, highlights, metrics, trend, top/bottom, next", "50 slides of appendix material, so the board can explore anything they want to see later and most modern teams have moved to exactly this way of doing things"], ans: 2, why: "Outline: (1) Title Slide, (2) Section Header \"Highlights\", (3) Top 3 metrics as a chart, (4) Trend analysis, (5) Two Content best vs worst performer, (6) Recommendations + Q&A. 10 min / 6 slides ≈ 1.5 min each. Name each slide's purpose within the time budget.", bloom: "create" },
  ],

  // ─── Topic 8: Slide Master, Transitions, Animations, Shortcuts ───
  8: [
    { q: "What does the Slide Master control?", opts: ["The default fonts, colours, backgrounds, and placeholders used across all slides","Only the very first slide of the deck, which acts as the template for the others","The slideshow timing settings only — how long each slide stays up during play","The speaker notes font and size only, not the main slide content the audience sees"], ans: 0, why: "Slide Master is the top-level template — edit once, apply everywhere. Layout Masters beneath it inherit its styling. Change a logo on the master once and every slide updates. Timings and notes are separate features.", bloom: "remember" },
    { q: "Which shortcut starts a PowerPoint slideshow from the beginning?", opts: ["F5, which is the standard shortcut for starting the slideshow from the first slide","Shift+F5, which starts the slideshow from the currently selected slide instead","Ctrl+F5, which is not a PowerPoint shortcut and does nothing in the program at all","Alt+F5, which opens the Presenter View but does not start the show from slide 1"], ans: 0, why: "F5 = start from the beginning. Shift+F5 = start from current slide (useful for rehearsing one section). Ctrl+F5 and Alt+F5 are not the standard start-from-slide-1 shortcuts.", bloom: "remember" },
    { q: "Why is the distinction between Transition and Animation important in PowerPoint?", opts: ["They are the same thing — Microsoft just uses two names for a single feature group and most modern teams have moved to exactly this way of doing things", "Transitions play between slides; animations play within one slide (text or objects)", "Transitions only work on the first slide; animations only work on the last slide", "Animations only work on text boxes, and transitions only work on embedded images"], ans: 1, why: "Transition: fade/wipe from slide A to slide B. Animation: a bullet flying in, an image bouncing — effects within a single slide. Two different tabs, two different purposes. Mixing them wastes time configuring the wrong effect in the wrong place.", bloom: "understand" },
    { q: "Why should animations be used sparingly in a professional presentation?", opts: ["PowerPoint charges a small fee for each animation used beyond the free starter set and most modern teams have moved to exactly this way of doing things", "Animations physically slow down the computer when more than three are in the deck", "Excessive animation distracts from the message and makes the deck look unprofessional", "Animations only work on Windows PCs, so Mac users cannot see them at all"], ans: 2, why: "Too much animation distracts, wastes time as the audience waits for text to finish flying in, and looks amateur. Animations should build understanding (reveal a chart step by step), not decorate. Fees, slowdowns, and Mac/PC issues are not real reasons.", bloom: "understand" },
    { q: "You want to start a slideshow from slide 1 for an audience. Which shortcut?", opts: ["Shift+F5, which starts the presentation from the currently selected slide, not slide 1","F5, which starts the slideshow from the very first slide of the whole deck","Ctrl+F5, which is not actually a PowerPoint shortcut for starting a slideshow","Alt+F5, which opens the Presenter View without starting the show from slide 1"], ans: 1, why: "F5 = start from the beginning. Shift+F5 = start from current slide. Ctrl+F5 and Alt+F5 are not the standard start-from-beginning shortcuts.", bloom: "apply" },
    { q: "You need to add your company's logo to every slide of a 50-slide deck. What is the efficient way?", opts: ["Paste the logo onto each slide individually, which guarantees it appears everywhere and most modern teams have moved to exactly this way of doing things", "Paste the logo once onto the Slide Master, and every slide inherits it automatically", "Email the logo to yourself so you can drag it from the email to each slide quickly", "Use a separate image file for every single slide to keep the file size down overall"], ans: 1, why: "Open View → Slide Master, paste the logo onto the top Master slide, and every slide inherits it. The whole point is \"edit once, apply everywhere\" — pasting 50 times is the wrong instinct when the tool exists exactly to avoid that.", bloom: "apply" },
    { q: "You want a bullet list to appear one bullet at a time as you click. Which feature?", opts: ["A Slide Transition set to Fade between bullets on the same slide for a clean look","An Animation on the bullet list with \"By Paragraph\" set, so bullets appear per click","A separate slide for every single bullet, so clicking moves to the next bullet's slide","The Slide Master, which handles anything that happens within a single slide automatically"], ans: 1, why: "Animation → Appear (or Fade) on the bullet list, with \"By Paragraph\" ensures one bullet appears per click. Transitions move between slides. One-slide-per-bullet works but is overkill. Slide Master is for template-level styling, not click animations.", bloom: "apply" },
    { q: "A presenter says their deck looks fine on their laptop but fonts change on the conference-room PC. Analyse the cause.", opts: ["The conference-room PC is probably broken and needs to be repaired before the talk", "The deck file is corrupted and needs to be rebuilt entirely from scratch on a new PC and most modern teams have moved to exactly this way of doing things", "PowerPoint randomly changes fonts on different computers due to a well-known glitch", "Missing fonts on the other PC — embed fonts in the file or use common ones like Arial"], ans: 3, why: "Fonts live on the OS, not in the file by default. When opened elsewhere without the font, PowerPoint substitutes a default. Fix: embed fonts (File → Options → Save → Embed fonts) or stick to common fonts (Calibri, Arial, Times New Roman).", bloom: "analyze" },
    { q: "A designer adds 8 different animations on every slide \"to keep the audience engaged.\" Evaluate.", opts: ["Great — the more motion on every slide, the more engaging the whole talk becomes","Even better would be 12 animations per slide, for maximum audience attention capture","Makes no real difference either way — the audience mostly listens to the speaker anyway","Counterproductive — animations should be purposeful, not decorative, or they distract"], ans: 3, why: "Excessive animation distracts, wastes time as text flies in, and looks amateur. Animations should BUILD understanding (reveal a chart step by step, surface a surprise), not decorate. Name the audience-cost of pointless motion.", bloom: "evaluate" },
    { q: "Design the Slide Master setup for a consulting firm's standard template. What goes on master vs individual slides?", opts: ["Everything on individual slides, so each slide can be styled exactly as needed that day","Skip the master entirely — let every presenter freestyle the design of every slide","Master holds branding (logo, colours, fonts, footer); slides hold the actual content","Put the whole presentation on the master slide, so it is easier to edit in one place"], ans: 2, why: "Master: company logo (top-right), client name placeholder, page number, brand colours, heading + body fonts, confidentiality footer. Individual slides: actual content. Result: consistent branding with no per-slide maintenance. Decide what is global (brand) vs per-slide (content).", bloom: "create" },
  ],

  // ─── Topic 9: Choosing the Right Tool (Word vs Excel vs PowerPoint) ───
  9: [
    { q: "What is the \"golden rule\" for picking Word, Excel, or PowerPoint?", opts: ["Word for documents, Excel for data and calculations, PowerPoint for presenting","Word for everything, because it is the oldest and most familiar tool in the suite","Excel for everything, because it has the most features and the most flexibility","PowerPoint for everything, because visual delivery works best for every audience"], ans: 0, why: "Word = writing/reading (documents). Excel = calculations and tabular data. PowerPoint = visual delivery to an audience. Tool fit follows purpose; the easiest mistake is forcing one job onto the wrong tool.", bloom: "remember" },
    { q: "Which tool is best for writing a multi-page essay with headings and citations?", opts: ["Excel, because its cells can be merged to create a paragraph layout for the essay and most modern teams have moved to exactly this way of doing things", "Word, because it handles paragraphs, headings, citations, and page numbers natively", "PowerPoint, because slides can hold lots of text and be printed at the end", "Notepad, because plain text is simpler than any other writing tool available"], ans: 1, why: "Word is the document tool — paragraphs, headings, citations, footnotes, page numbers, TOC. Excel is for grids and numbers. PowerPoint is for slides, not essays. Notepad has no formatting. Use the right tool for the job.", bloom: "remember" },
    { q: "Why do most people still reach for Word for a resume instead of a visual tool like Canva?", opts: ["Word is much cheaper than Canva, which costs money for every single template","Canva is a new tool that does not exist in most schools or offices yet, so Word wins","PowerPoint has no text feature, so even a simple resume must be written in Word first","Applicant Tracking Systems parse Word text reliably but struggle with visual exports"], ans: 3, why: "Resumes are read by humans AND screened by ATS. Word's text-first format is parseable; heavily visual tools often produce PDFs with text-as-images that ATS cannot read. Tool fit must consider the downstream reader (ATS), not just the human.", bloom: "understand" },
    { q: "Why would you NOT write a 10-page essay in Excel, even though Excel cells can hold text?", opts: ["Excel has a strict word limit per cell and the essay will simply not fit inside","Excel files are too large to share by email or upload to the university website","No paragraph flow, no styles, no page numbers, and printing is ugly across pages","Excel cannot actually hold more than a single line of text in each individual cell"], ans: 2, why: "Excel is a grid; essays are prose. A grid does not flow text across pages, has no paragraph styles, no pagination, and prints awkwardly. Word was built for prose; using Excel forfeits every reason we write essays in the first place.", bloom: "understand" },
    { q: "HR needs to track attendance for 300 employees with sort, filter, and formula capability. Which tool?", opts: ["Word with a big table, because tables in Word can store exactly the same data", "PowerPoint with text boxes, because it can show tables to an audience on screen", "Excel, because tabular data with calculations, sort, and filter is Excel's core job", "Notepad, because plain text is the simplest way to store a list of employee names and most modern teams have moved to exactly this way of doing things"], ans: 2, why: "Tabular data + calculations + sort/filter = Excel. Word tables cannot sort, filter, or compute at scale. PowerPoint is the wrong universe entirely. Notepad has no formulas. Apply the golden rule.", bloom: "apply" },
    { q: "A founder must (a) write an investor pitch document, (b) build a 3-year revenue forecast, (c) present live to investors. Match each to a tool.", opts: ["Word for all three, because a well-written document can cover every business need","Excel for all three, because forecasts, documents, and slides all involve data","PowerPoint for all three, because investors mainly respond to visual presentations","(a) Word, (b) Excel, (c) PowerPoint — each task matched to the tool built for it"], ans: 3, why: "(a) written document → Word. (b) numeric forecasts with formulas → Excel. (c) live audience → PowerPoint. Bonus: Office apps integrate, so the Excel forecast can live in both Word and PowerPoint as linked objects — single source of truth across tools.", bloom: "apply" },
    { q: "A small business wants to create a printed flyer with a logo, headline, and three bullet points. Which tool?", opts: ["Excel, because its grid can be used to align the logo and bullet points precisely and most modern teams have moved to exactly this way of doing things", "Notepad, because a flyer only needs basic plain text and does not need any images", "Word (or a dedicated design tool), because it handles images, headlines, and bullets", "A code editor, because precise positioning is easier with HTML-style markup tags"], ans: 2, why: "Word handles images, headlines, and bullet lists — good enough for a simple flyer. For fancier designs, tools like Canva or Publisher exist. Excel is for grids; Notepad has no images; code editors are for code, not flyers.", bloom: "apply" },
    { q: "A company uses Excel for writing all internal memos (\"one cell per paragraph\"). Analyse the downstream problems.", opts: ["No problems at all — Excel can hold text and the memos look roughly the same", "Memos will print in colour automatically, which wastes the company's printer toner and most modern teams have moved to exactly this way of doing things", "Excel will actually make the files smaller and easier to email around the office", "Broken formatting, ugly printing, no TOC or navigation, clumsy collaboration comments"], ans: 3, why: "Specific losses: no formatting continuity (spell-check per cell, no paragraph styles), ugly printing (row heights do not match prose), no navigation or TOC, awkward comments. Memos are prose — they belong in a document tool, not a grid.", bloom: "analyze" },
    { q: "A university wants to standardise on Google Docs for EVERYTHING — documents, spreadsheets, presentations. Evaluate.", opts: ["Brilliant — having one single tool for every kind of output wins on consistency alone and most modern teams have moved to exactly this way of doing things", "Terrible — Google has no office tools capable of replacing Microsoft Office at all", "It does not matter what tool is standardised — outputs all look the same anyway", "Partly correct — fine for most tasks, but Sheets and Slides lack some power-user features"], ans: 3, why: "Docs/Sheets/Slides cover the three categories and support collaboration well. But Sheets is weaker for large/complex spreadsheets and Slides has fewer animation options than PowerPoint. For most students and small teams the trade-off is fine; for power users it constrains. A blanket yes/no misses the trade-off.", bloom: "evaluate" },
    { q: "Design a workflow for a consulting team writing 50-page reports with charts and presenting summaries to clients.", opts: ["Excel as the data source, linked into a Word report and a PowerPoint deck for clients","Put everything into Word, because the report is the most important deliverable of all","Put everything into Excel, because the data is what drives both report and presentation","Skip having a workflow — let each team member pick whichever tools feel easiest to use"], ans: 0, why: "Excel: source of all data and charts (single source of truth). Word: the 50-page report, with Excel charts embedded as linked objects. PowerPoint: the client deck, also embedding the same Excel charts. Updating Excel once updates both. The classic consulting pattern — avoids drift between report and deck.", bloom: "create" },
  ],
};
